const now = DateTime.now().setZone('America/New_York');
// Monday covers everything since Saturday's digest
const since = now.minus({ hours: now.weekday === 1 ? 48 : 24 });
const yes = v => v === true || String(v).toLowerCase() === 'true';

const calls = $input.all().map(i => i.json)
  .filter(r => r.timestamp && DateTime.fromISO(r.timestamp) >= since);

const line = r => `- ${r.name || 'Unknown caller'}, ${r.phone || 'no number'}: ${r.summary}`;
const urgent = calls.filter(r => yes(r.urgent));
const callback = calls.filter(r => !yes(r.urgent) && (yes(r.wants_callback) || (yes(r.new_client) && !yes(r.booked))));
const booked = calls.filter(r => yes(r.booked));
const other = calls.filter(r => !urgent.includes(r) && !callback.includes(r) && !booked.includes(r));

const section = (title, list) => list.length ? `${title} (${list.length})\n${list.map(line).join('\n')}\n\n` : '';

const body = calls.length === 0
  ? 'Good morning. No calls came in overnight.'
  : `Good morning. Sarah took ${calls.length} call${calls.length === 1 ? '' : 's'} since ${since.toFormat("cccc h:mm a")}.\n\n`
    + section('URGENT: IRS DEADLINE', urgent)
    + section('CALL BACK TODAY', callback)
    + section('BOOKED', booked)
    + section('OTHER CALLS', other)
    + 'Full notes are on each lead in Pipedrive.';

return [{ json: {
  subject: `Overnight calls: ${calls.length} (${urgent.length + callback.length} need a callback)`,
  body,
}}];
